<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Shared\Security;

use DateInterval;
use DateTime;
use Psr\Http\Message\ServerRequestInterface;
use Psr\SimpleCache\CacheInterface;
use Civi\Lughauth\Shared\AppConfig;

class MagicLinkService
{
    private const string CACHE_PREFIX = 'magic_link_';

    private readonly string $paramName;
    private readonly DateInterval $ttl;
    private readonly int $maxReads;

    public function __construct(private readonly CacheInterface $cache, AppConfig $config)
    {
        $this->paramName = (string) $config->get('security.magiclink.param', 'magic_link');
        $this->ttl = new DateInterval($config->get('security.magiclink.ttl', 'PT15M'));
        $this->maxReads = (int) $config->get('security.magiclink.reads', 3);
    }

    public function create(
        string $url,
        ?ServerRequestInterface $request,
        ?string $jwtToken = null,
        ?Identity $identity = null,
        ?Connection $connection = null
    ): string {
        if ($request == null && $jwtToken === null && $identity === null) {
            throw new \InvalidArgumentException('Magic link requires a JWT token or identity.');
        }

        if (null !== $request) {
            $jwtToken = $request->getHeader('Authorization')[0];
            $identity = null;
            $connection = null;
        }

        $magicToken = $this->generateToken();
        $payload = [
            'path' => $this->normalizePathAndQuery($url),
            'token' => $jwtToken,
            'identity' => $identity ? $this->serializeIdentity($identity) : null,
            'connection' => $connection ? $this->serializeConnection($connection) : null,
            'reads' => 0,
            'max' => $this->maxReads,
        ];

        $this->cache->set($this->cacheKey($magicToken), json_encode($payload), $this->ttl);

        return $this->appendParam($url, $this->paramName, $magicToken);
    }

    /**
     * @return array{token: ?string, identity: ?Identity, connection: ?Connection}|null
     */
    public function consume(ServerRequestInterface $request): ?array
    {
        $magicToken = $this->extractToken($request);
        if ($magicToken === null) {
            return null;
        }

        $cacheKey = $this->cacheKey($magicToken);
        if (!$this->cache->has($cacheKey)) {
            return null;
        }

        $raw = $this->cache->get($cacheKey);
        $data = is_string($raw) ? json_decode($raw, true) : null;
        if (!is_array($data)) {
            $this->cache->delete($cacheKey);
            return null;
        }

        $expectedPath = $data['path'] ?? null;
        if (!is_string($expectedPath) || $expectedPath === '') {
            return null;
        }

        $currentPath = $this->normalizeRequestPathAndQuery($request);
        if ($currentPath !== $expectedPath) {
            return null;
        }

        $reads = (int) ($data['reads'] ?? 0);
        $maxReads = (int) ($data['max'] ?? $this->maxReads);
        $reads++;
        $data['reads'] = $reads;

        if ($reads >= $maxReads) {
            $this->cache->delete($cacheKey);
        } else {
            $this->cache->set($cacheKey, json_encode($data), $this->ttl);
        }

        $jwtToken = isset($data['token']) && is_string($data['token']) && $data['token'] !== '' ? $data['token'] : null;
        $identity = isset($data['identity']) && is_array($data['identity']) ? $this->deserializeIdentity($data['identity']) : null;
        $connection = isset($data['connection']) && is_array($data['connection']) ? $this->deserializeConnection($data['connection']) : null;

        if ($jwtToken === null && $identity === null) {
            return null;
        }

        return [
            'token' => $jwtToken,
            'identity' => $identity,
            'connection' => $connection,
        ];
    }

    private function extractToken(ServerRequestInterface $request): ?string
    {
        $query = $request->getQueryParams();
        $value = $query[$this->paramName] ?? null;
        if (is_array($value)) {
            $value = reset($value);
        }
        return is_string($value) && $value !== '' ? $value : null;
    }

    private function normalizeRequestPathAndQuery(ServerRequestInterface $request): string
    {
        $path = $request->getUri()->getPath();
        if ($path === '') {
            $path = '/';
        }
        $query = $request->getUri()->getQuery();
        $params = [];
        if ($query !== '') {
            parse_str($query, $params);
        }
        unset($params[$this->paramName]);
        $queryString = http_build_query($params);
        return $queryString === '' ? $path : $path . '?' . $queryString;
    }

    private function normalizePathAndQuery(string $url): string
    {
        $parts = parse_url($url);
        if ($parts === false) {
            return $url;
        }
        $path = $parts['path'] ?? '';
        if ($path === '') {
            $path = '/';
        }
        $params = [];
        if (isset($parts['query'])) {
            parse_str($parts['query'], $params);
        }
        unset($params[$this->paramName]);
        $queryString = http_build_query($params);
        return $queryString === '' ? $path : $path . '?' . $queryString;
    }

    private function appendParam(string $url, string $name, string $value): string
    {
        $parts = parse_url($url);
        if ($parts === false) {
            $separator = str_contains($url, '?') ? '&' : '?';
            return $url . $separator . rawurlencode($name) . '=' . rawurlencode($value);
        }

        $params = [];
        if (isset($parts['query'])) {
            parse_str($parts['query'], $params);
        }
        $params[$name] = $value;
        $queryString = http_build_query($params);

        $scheme = $parts['scheme'] ?? '';
        $host = $parts['host'] ?? '';
        $port = isset($parts['port']) ? ':' . $parts['port'] : '';
        $user = $parts['user'] ?? '';
        $pass = $parts['pass'] ?? '';
        $auth = $user !== '' ? $user . ($pass !== '' ? ':' . $pass : '') . '@' : '';
        $path = $parts['path'] ?? '';
        $fragment = isset($parts['fragment']) ? '#' . $parts['fragment'] : '';

        $base = '';
        if ($scheme !== '' && $host !== '') {
            $base = $scheme . '://' . $auth . $host . $port;
        }

        $full = $base . $path;
        if ($queryString !== '') {
            $full .= '?' . $queryString;
        }

        return $full . $fragment;
    }

    private function cacheKey(string $token): string
    {
        return self::CACHE_PREFIX . $token;
    }

    private function generateToken(): string
    {
        return rtrim(strtr(base64_encode(random_bytes(24)), '+/', '-_'), '=');
    }

    private function serializeIdentity(Identity $identity): array
    {
        return [
            'anonymous' => $identity->anonymous,
            'authScope' => $identity->authScope,
            'id' => $identity->id,
            'name' => $identity->name,
            'token' => $identity->token,
            'issuer' => $identity->issuer,
            'tenant' => $identity->tenant,
            'roles' => $identity->roles,
            'groups' => $identity->groups,
            'claims' => $identity->claims,
            'scope' => $identity->scope,
            'email' => $identity->email,
        ];
    }

    private function serializeConnection(Connection $connection): array
    {
        return [
            'level' => $connection->level,
            'remote' => $connection->remote,
            'startTime' => $connection->startTime->format(DateTime::ATOM),
            'application' => $connection->application,
            'callback' => $connection->callback,
            'source' => $connection->source,
            'target' => $connection->target,
            'locale' => $connection->locale,
        ];
    }

    private function deserializeIdentity(array $data): Identity
    {
        return new Identity(
            anonymous: (bool) ($data['anonymous'] ?? true),
            authScope: $data['authScope'] ?? Identity::AUTH_SCOPE_NONE,
            id: $data['id'] ?? null,
            name: $data['name'] ?? null,
            token: $data['token'] ?? null,
            issuer: $data['issuer'] ?? null,
            tenant: $data['tenant'] ?? null,
            roles: $data['roles'] ?? null,
            groups: $data['groups'] ?? null,
            claims: $data['claims'] ?? null,
            scope: $data['scope'] ?? null,
            email: $data['email'] ?? null
        );
    }

    private function deserializeConnection(array $data): Connection
    {
        $startTime = isset($data['startTime']) ? new DateTime((string) $data['startTime']) : new DateTime();
        return new Connection(
            level: isset($data['level']) ? (int) $data['level'] : 0,
            remote: (bool) ($data['remote'] ?? true),
            startTime: $startTime,
            application: (string) ($data['application'] ?? ''),
            callback: (string) ($data['callback'] ?? ''),
            source: (string) ($data['source'] ?? ''),
            target: (string) ($data['target'] ?? ''),
            locale: $data['locale'] ?? null
        );
    }
}
